  "reservation": "def next_commands(event, order):
    total_reserved = event.get("reserved", 0)
    cash = event.get("cash", 0)
    cost = order["price"] * order["qty"]
    if cost <= (cash - total_reserved) and order["qty"] <= 10:
        return [{"type": "approve"}]
    return []
",
  "retry": "def next_commands(event, order):
    if not order.get("approved", False):
        return []
    if order.get("status") in ("cancelled", "filled"):
        return []
    if event["kind"] == "submit" or event["kind"] == "timeout":
        return [{"type": "submit", "client_order_id": order["order_id"], "price": order["price"], "qty": order["qty"]}]
    return []
